<script setup lang="ts">import { computed,ref } from 'vue';import { ElDrawer,ElSlider } from 'element-plus';import { useUiStore } from '../../stores/ui.store';import { useRadioStore } from '../../stores/radio.store';import { useRadioSchedulesStore } from '../../stores/radioSchedules.store';const ui=useUiStore(),radio=useRadioStore(),schedules=useRadioSchedulesStore(),q=ref('');const list=computed(()=>radio.stations.filter(s=>s.enabled&&(!q.value||s.name.toLowerCase().includes(q.value.toLowerCase()))))</script><template><ElDrawer v-model="ui.radioOpen" title="Radio" size="min(460px, 94vw)" class="radio-drawer"><div class="radio-now"><div class="eyebrow">{{radio.playing?'In ascolto':'Radio'}}</div><strong>{{radio.current?.name||'Scegli una stazione'}}</strong><a v-if="radio.current?.website" :href="radio.current.website" target="_blank" rel="noopener">Sito della stazione ↗</a><div v-if="radio.error" class="error">{{radio.error}}</div><div class="radio-controls"><button class="mainplay" @click="radio.toggle">{{radio.playing?'Ⅱ':'▶'}}</button><button class="quiet-button" @click="radio.surprise">Sorprendimi</button></div><div class="volume"><span>Volume</span><ElSlider :model-value="radio.volume" :min="0" :max="1" :step=".01" @update:model-value="v=>radio.setVolume(Number(v))"/></div></div><div class="schedule-hint"><div class="eyebrow">Programmazione</div><span v-if="schedules.next">Prossimo avvio {{schedules.next.date.toLocaleString('it-IT',{weekday:'short',hour:'2-digit',minute:'2-digit'})}} · {{radio.stations.find(x=>x.id===schedules.next?.s.stationId)?.name}}</span><span v-else>Nessun prossimo avvio programmato</span></div><input v-model="q" class="station-search" placeholder="Cerca stazione…"/><div class="stations"><button v-for="s in list" :key="s.id" :class="{active:s.id===radio.currentId}" @click="radio.play(s)"><span><b>{{s.name}}</b><small>{{s.provider}}</small></span><em v-if="!s.streamUrl">da configurare</em><i v-else>▶</i></button></div></ElDrawer></template><style scoped>.radio-now{padding:.3rem 0 1.2rem;border-bottom:1px solid var(--glass-border);display:grid;gap:.5rem}.radio-now strong{font-family:var(--font-serif);font-size:1.35rem}.radio-now a{color:var(--text-secondary);font-size:var(--font-sm);text-decoration:none}.error{color:var(--warning);font-size:var(--font-sm)}.radio-controls{display:flex;align-items:center;gap:.7rem;margin-top:.5rem}.mainplay{width:52px;height:52px;border-radius:50%;border:1px solid var(--glass-border);background:var(--accent);color:#142019;font-size:1.1rem}.volume{display:grid;grid-template-columns:auto 1fr;align-items:center;gap:1rem}.schedule-hint{margin-top:1.1rem;padding-top:1rem;border-top:1px solid var(--glass-border);display:grid;gap:.25rem;color:var(--text-secondary);font-size:var(--font-sm)}.station-search{width:100%;margin:1rem 0;padding:.8rem 1rem;border-radius:14px;border:1px solid var(--glass-border);background:rgba(255,255,255,.04);color:inherit}.stations{display:grid}.stations button{display:flex;align-items:center;justify-content:space-between;gap:1rem;padding:.85rem .2rem;border:0;border-bottom:1px solid rgba(255,255,255,.07);background:transparent;color:inherit;text-align:left}.stations button span{display:grid}.stations small{color:var(--text-muted)}.stations em{font-size:.7rem;color:var(--text-muted)}.stations .active b{color:var(--accent)}</style>
